css:
.invoice-wrapper {
  font-family: "Times New Roman", serif;
  font-size: 12px;
  color: #000;
}
.header {
  text-align: center;
  margin-bottom: 8px;
}
.title h2 {
  margin: 0;
  font-size: 18px;
}
.vat-no {
  font-weight: bold;
  margin-bottom: 6px;
}
.info-table,
.items-table,
.totals-table,
.signature-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
}
.box {
  border: 1px solid #000;
  padding: 6px 8px;
  vertical-align: top;
}
.inner-table td {
  padding: 2px 4px;
  vertical-align: middle;
}
.items-table th,
.items-table td {
  border: 1px solid #000;
  padding: 5px;
}
.items-table th {
  background: #f8f8f8;
}
.center {
  text-align: center;
}
.right {
  text-align: right;
}
.desc {
  text-align: left;
  min-height: 60px;
}
.end-row td {
  font-weight: bold;
  padding: 10px;
}
.totals-table {
  border: 1px solid #000;
}
.summary-table {
  width: 100%;
}
.summary-table td {
  padding: 4px 6px;
}
.summary-table .ar {
  text-align: right;
  width: 45%;
}
.summary-table .en {
  text-align: left;
  width: 30%;
}
.summary-table .right {
  width: 25%;
  font-weight: bold;
}
.grand td {
  font-weight: bold;
}
.amount-words-cell {
  vertical-align: bottom;
  padding: 8px;
  font-size: 11px;
  line-height: 1.4;
}
.received {
  text-align: center;
  margin: 20px 0;
  font-size: 11px;
  font-style: italic;
}
.signature-table td {
  padding-top: 50px;
  text-align: center;
}
.signature-table .left {
  text-align: left;
}
.signature-table .right {
  text-align: right;
}
.footer {
  margin-top: 25px;
  padding-top: 8px;
  display: flex;
  justify-content: space-between;
  font-size: 10px;
}
.footer-table {
  width: 100%;
  margin-top: 25px;
  font-size: 10px;
  border: none;
}
.footer-table td {
  width: 50%;
  vertical-align: top;
  padding: 0 10px;   /* optional – adds a bit of separation */
  line-height: 1.4;
}
.footer-table .footer-left {
  padding-left: 0;
}
.footer-table .footer-right {
  padding-right: 0;
  text-align: right;   /* optional – right-align Sharjah block if you like */
}
